{"path":"/home/roko/Documents/Projects/myactuator/firmware/esp32/src/protocols/pal.h","content":"#ifndef PAL_H
#define PAL_H

#include <stdint.h>
#include <stdbool.h>

// Protocol Abstraction Layer - Motor Actuator Interface
// Based on EPS-RH-20-100-1 specifications

#define PAL_PROTOCOL_VERSION 1
#define PAL_MAX_MOTORS 4
#define PAL_BUFFER_SIZE 256

// Motor state structure
typedef struct {
    uint16_t position;      // Current position (encoder counts)
    int16_t velocity;       // Current velocity (counts/sec)
    int16_t current;        // Motor current (mA)
    bool enabled;           // Motor enabled state
    uint8_t error_code;     // Error status
} MotorState_t;

// PAL command structure
typedef struct {
    uint8_t motor_id;
    uint8_t command;
    uint16_t parameter;
    uint8_t data[32];
} PAL_Command_t;

// PAL response structure
typedef struct {
    uint8_t motor_id;
    uint8_t status;
    uint16_t response_data;
    uint8_t data[32];
} PAL_Response_t;

// PAL interface functions
typedef struct {
    bool (*init)(void);
    bool (*send_command)(const PAL_Command_t *cmd);
    bool (*receive_response)(PAL_Response_t *resp, uint32_t timeout_ms);
    bool (*get_motor_state)(uint8_t motor_id, MotorState_t *state);
    void (*deinit)(void);
} PAL_Interface_t;

// CAN bus configuration for PAL
#define CAN_BUS_BAUDRATE 500000
#define CAN_BUS_NODE_ID 1

// Protocol commands (from specification table line 14+)
#define CMD_MOTOR_ENABLE    0x01
#define CMD_MOTOR_DISABLE   0x02
#define CMD_SET_POSITION    0x03
#define CMD_SET_VELOCITY    0x04
#define CMD_READ_STATE      0x05
#define CMD_CALIBRATE       0x06

#endif // PAL_H
